"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[23230],{55074:e=>{e.exports=JSON.parse('{"month":"2026-07","entries":[{"id":"2026-07-30-webchat-content-security-policy-guide","date":"2026-07-30","products":["Actions & Events"],"product":"Actions & Events","channel":"WebChat","changeType":"Added","title":"WebChat Content-Security-Policy guide","excerpt":"Embedding the 8x8 WebChat v2 widget behind a strict Content-Security-Policy meant guessing which directives to allow. A new Content Security Policy guide documents exactly what your embedding page\'s CSP needs.","hasArticle":true},{"id":"2026-07-28-verification-api-templatekey-parameter","date":"2026-07-28","products":["Connect","APIs"],"product":"Connect","channel":"Verification","changeType":"Changed","title":"Verification API templateKey parameter","excerpt":"The Verification API request now accepts a templateKey parameter, letting you select a pre-saved message template by its key instead of supplying the message content inline. The example values used across the Verification API documentation have also been standardised.","hasArticle":true},{"id":"2026-07-28-whatsapp-automatic-events-webhook","date":"2026-07-28","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Automatic Events webhook","excerpt":"You can now receive WhatsApp Automatic Events webhooks \u2014 notifications sent when Meta detects a qualifying conversion event (a purchase or a lead) inside a WhatsApp thread that originated from a Click-to-WhatsApp ad. 8x8 forwards these detected events to your endpoint so you can feed conversion data into your own analy\u2026","hasArticle":true},{"id":"2026-07-27-work-analytics-metrics-and-real-time-report-guides","date":"2026-07-27","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Added","title":"Work Analytics metrics and real-time report guides","excerpt":"The Work Analytics documentation now covers the full metric set for per-agent reporting, and the two guides that back the live agent and queue views have been published.","hasArticle":true},{"id":"2026-07-23-agentaveragetimetoanswer-metric","date":"2026-07-23","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Added","title":"agentAverageTimeToAnswer metric","excerpt":"The agentAverageTimeToAnswer metric is now documented on the Work Analytics agent-activity endpoints. It is a timing metric, reported in seconds, and sits alongside the other agent timing metrics such as agentTotalTalkTime, averageTalkingInteractionsTime, averageOnHoldInteractionsTime, and averageWrapUpTime.","hasArticle":true},{"id":"2026-07-21-business-scoped-user-ids-bsuid","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"Business-Scoped User IDs (BSUID)","excerpt":"WhatsApp is rolling out optional usernames, which let people message a business without handing over their phone number. So that those users stay reachable, Meta gives every WhatsApp user a persistent Business-Scoped User ID (BSUID). 8x8 now surfaces the BSUID as user.channelUserId throughout the WhatsApp over 8x8 API.\u2026","hasArticle":true},{"id":"2026-07-21-outbound-context-on-outbound-api-v9","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Changed","title":"Outbound context on Outbound API v9","excerpt":"Outbound Messaging Apps delivery receipts on version 9 now carry additional context about the message they refer to. A new outboundContent object gives you a structured, channel-normalized copy of the WhatsApp message that was delivered, so you can reconcile a delivery receipt with the exact content sent without keepin\u2026","hasArticle":true},{"id":"2026-07-17-moobidesk-renamed-to-converse","date":"2026-07-17","products":["Converse"],"product":"Converse","channel":"","changeType":"Changed","title":"Moobidesk renamed to Converse","excerpt":"The product previously known as Moobidesk is now called Converse throughout the developer documentation. All functionality is identical \u2014 only the product name has changed, so there is no API or behavioural change to act on.","hasArticle":true},{"id":"2026-07-17-release-6869-meeting-features","date":"2026-07-17","products":["JaaS"],"product":"JaaS","channel":"","changeType":"Added","title":"Release 6869 meeting features","excerpt":"JaaS release 6869 adds a set of in-meeting improvements across subtitles, the whiteboard, and recording and transcription controls.","hasArticle":true},{"id":"2026-07-16-contact-center-analytics-release-2-14","date":"2026-07-16","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Added","title":"Contact Center Analytics release 2.14","excerpt":"The Contact Center Analytics documentation set has been refreshed for the 2.14 release.","hasArticle":true},{"id":"2026-07-16-whatsapp-request-call-info","date":"2026-07-16","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Request Call Info","excerpt":"You can now check a customer\'s WhatsApp call permission status before you place a business-initiated call. Meta requires customers to explicitly grant permission before a business can call them on WhatsApp, and the new Get Call Permission Status endpoint tells you whether that permission is in place, whether you are cu\u2026","hasArticle":true},{"id":"2026-07-07-chat-apps-inbound-and-outbound-messaging","date":"2026-07-07","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Added","title":"Chat Apps inbound and outbound messaging","excerpt":"You can now follow end-to-end how-to documentation for sending and receiving Chat Apps messages on the 8x8 platform. The Chat Apps API lets you reach customers across supported channels \u2014 WhatsApp, Viber, RCS, LINE, and others \u2014 through a single message API, and receive their replies and delivery updates on the webhook\u2026","hasArticle":true},{"id":"2026-07-06-ring-group-management-api-update-members","date":"2026-07-06","products":["Administration"],"product":"Administration","channel":"","changeType":"Changed","title":"Ring Group Management API update-members","excerpt":"The Ring Group Management API guide now documents a dedicated endpoint for targeted membership changes. Instead of reading a ring group, mutating its full member list, and writing the whole object back with PUT, you can send only the members that are changing.","hasArticle":true},{"id":"2026-07-03-api-versioning-header-guidance-corrected","date":"2026-07-03","products":["Administration"],"product":"Administration","channel":"","changeType":"Fixed","title":"API versioning header guidance corrected","excerpt":"We have corrected the API versioning guidance for the Administration API Suite to make clear which header carries the version on which kind of request.","hasArticle":true},{"id":"2026-07-03-maestro-sdk-iframe-microphone-and-speaker","date":"2026-07-03","products":["Tech Partner"],"product":"Tech Partner","channel":"","changeType":"Added","title":"Maestro SDK iframe microphone and speaker","excerpt":"When you embed the Maestro SDK in an <iframe, loading the URL on its own isn\'t enough to enable audio \u2014 modern browsers block microphone capture and speaker selection unless the embedding page explicitly grants them. The Maestro SDK overview now documents the allow attribute you need so that call and audio features wor\u2026","hasArticle":true},{"id":"2026-07-02-administration-api-suite-changelog","date":"2026-07-02","products":["Administration"],"product":"Administration","channel":"","changeType":"Added","title":"Administration API Suite changelog","excerpt":"The Administration API Suite now has a dedicated changelog so you can track every change to the suite in one place, newest first. Whenever an API in the suite gains a new capability, changes behaviour, or has its documentation clarified, the change is recorded there.","hasArticle":true}]}')}}]);